ST.html:p:
IF FirstScan THEN
    LOOP_2917_TRIP  := TRUE;
    LOOP_2901A_TRIP := TRUE;
    LOOP_2901B_TRIP := TRUE;
    SAFE_STATE      := TRUE;
    MCC_2901A       := FALSE;
    MCC_2901B       := FALSE;
    PSD_2917        := FALSE;
    ESD_3200        := FALSE;
    XV_RS_001A_TOP  := FALSE;
    XV_RS_001A_BOT  := FALSE;
    XV_RS_001B_TOP  := FALSE;
    XV_RS_001B_BOT  := FALSE;
    HY_2903A_Out    := 6554;
    HY_2903B_Out    := 6554;
    KV_2904_Out     := 6554;
    PumpA_Run       := FALSE;
    PumpB_Run       := FALSE;
    FirstScan       := FALSE;
    RETURN;
END_IF;

ESTOP := HS_EMERGENCY_STOP_A_2901A OR HS_EMERGENCY_STOP_B_2901B;

TI_2909_Scaled   := ((INT_TO_REAL(TI_2909_Raw)   - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_2917HH_Scaled := ((INT_TO_REAL(TI_2917HH_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TT_2909_Scaled   := ((INT_TO_REAL(TT_2909_Raw)   - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TT_2911_Scaled   := ((INT_TO_REAL(TT_2911_Raw)   - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TT_2917_Scaled   := ((INT_TO_REAL(TT_2917_Raw)   - 6554.0) / (32767.0 - 6554.0)) * 150.0;
XI_2901A_Scaled  := ((INT_TO_REAL(XI_2901A_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;
XI_2901B_Scaled  := ((INT_TO_REAL(XI_2901B_Raw)  - 6554.0) / (32767.0 - 6554.0)) * 100.0;

TT_2917_HH    := TT_2917_Scaled > TT_2917_HH_SP;
TT_2917_LL    := TT_2917_Scaled < TT_2917_LL_SP;
VSHH_2901A_HH := VSHH_2901A;
VSHH_2901A_LL := FALSE;
VSHH_2901B_HH := VSHH_2901B;
VSHH_2901B_LL := FALSE;

IF TT_2917_HH OR TT_2917_LL THEN
    LOOP_2917_TRIP := TRUE;
ELSIF LOOP_2917_TRIP AND MANUAL_RESET AND NOT TT_2917_HH AND NOT TT_2917_LL THEN
    LOOP_2917_TRIP := FALSE;
END_IF;

IF VSHH_2901A_HH OR VSHH_2901A_LL THEN
    LOOP_2901A_TRIP := TRUE;
ELSIF LOOP_2901A_TRIP AND MANUAL_RESET AND NOT VSHH_2901A_HH AND NOT VSHH_2901A_LL THEN
    LOOP_2901A_TRIP := FALSE;
END_IF;

IF VSHH_2901B_HH OR VSHH_2901B_LL THEN
    LOOP_2901B_TRIP := TRUE;
ELSIF LOOP_2901B_TRIP AND MANUAL_RESET AND NOT VSHH_2901B_HH AND NOT VSHH_2901B_LL THEN
    LOOP_2901B_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP OR LOOP_2917_TRIP OR LOOP_2901A_TRIP OR LOOP_2901B_TRIP;

ESD_3200 := NOT SAFE_STATE;
PSD_2917 := NOT LOOP_2917_TRIP;

TI_2909_HH_Latch(S1 := TI_2909_Scaled > TI_2909_HH_SP,
                 R  := TI_2909_HH_Ack AND (TI_2909_Scaled <= (TI_2909_HH_SP - TI_2909_Deadband)));
IF TI_2909_Scaled > TI_2909_H_SP THEN
    TI_2909_H := TRUE;
ELSIF TI_2909_Scaled <= (TI_2909_H_SP - TI_2909_Deadband) THEN
    TI_2909_H := FALSE;
END_IF;
IF TI_2909_Scaled < TI_2909_L_SP THEN
    TI_2909_L := TRUE;
ELSIF TI_2909_Scaled >= (TI_2909_L_SP + TI_2909_Deadband) THEN
    TI_2909_L := FALSE;
END_IF;
TI_2909_LL_Latch(S1 := TI_2909_Scaled < TI_2909_LL_SP,
                 R  := TI_2909_LL_Ack AND (TI_2909_Scaled >= (TI_2909_LL_SP + TI_2909_Deadband)));

TT_2909_HH_Latch(S1 := TT_2909_Scaled > TT_2909_HH_SP,
                 R  := TT_2909_HH_Ack AND (TT_2909_Scaled <= (TT_2909_HH_SP - TT_2909_Deadband)));
IF TT_2909_Scaled > TT_2909_H_SP THEN
    TT_2909_H := TRUE;
ELSIF TT_2909_Scaled <= (TT_2909_H_SP - TT_2909_Deadband) THEN
    TT_2909_H := FALSE;
END_IF;
IF TT_2909_Scaled < TT_2909_L_SP THEN
    TT_2909_L := TRUE;
ELSIF TT_2909_Scaled >= (TT_2909_L_SP + TT_2909_Deadband) THEN
    TT_2909_L := FALSE;
END_IF;
TT_2909_LL_Latch(S1 := TT_2909_Scaled < TT_2909_LL_SP,
                 R  := TT_2909_LL_Ack AND (TT_2909_Scaled >= (TT_2909_LL_SP + TT_2909_Deadband)));

TT_2911_HH_Latch(S1 := TT_2911_Scaled > TT_2911_HH_SP,
                 R  := TT_2911_HH_Ack AND (TT_2911_Scaled <= (TT_2911_HH_SP - TT_2911_Deadband)));
IF TT_2911_Scaled > TT_2911_H_SP THEN
    TT_2911_H := TRUE;
ELSIF TT_2911_Scaled <= (TT_2911_H_SP - TT_2911_Deadband) THEN
    TT_2911_H := FALSE;
END_IF;
IF TT_2911_Scaled < TT_2911_L_SP THEN
    TT_2911_L := TRUE;
ELSIF TT_2911_Scaled >= (TT_2911_L_SP + TT_2911_Deadband) THEN
    TT_2911_L := FALSE;
END_IF;
TT_2911_LL_Latch(S1 := TT_2911_Scaled < TT_2911_LL_SP,
                 R  := TT_2911_LL_Ack AND (TT_2911_Scaled >= (TT_2911_LL_SP + TT_2911_Deadband)));

TT_2917_HH_Latch(S1 := TT_2917_Scaled > TT_2917_HH_SP,
                 R  := TT_2917_HH_Ack AND (TT_2917_Scaled <= (TT_2917_HH_SP - TT_2917_Deadband)));
IF TT_2917_Scaled > TT_2917_H_SP THEN
    TT_2917_H := TRUE;
ELSIF TT_2917_Scaled <= (TT_2917_H_SP - TT_2917_Deadband) THEN
    TT_2917_H := FALSE;
END_IF;
IF TT_2917_Scaled < TT_2917_L_SP THEN
    TT_2917_L := TRUE;
ELSIF TT_2917_Scaled >= (TT_2917_L_SP + TT_2917_Deadband) THEN
    TT_2917_L := FALSE;
END_IF;
TT_2917_LL_Latch(S1 := TT_2917_Scaled < TT_2917_LL_SP,
                 R  := TT_2917_LL_Ack AND (TT_2917_Scaled >= (TT_2917_LL_SP + TT_2917_Deadband)));

TI_2917HH_HH_Latch(S1 := TI_2917HH_Scaled > TI_2917HH_HH_SP,
                   R  := TI_2917HH_HH_Ack AND (TI_2917HH_Scaled <= (TI_2917HH_HH_SP - TI_2917HH_Deadband)));
IF TI_2917HH_Scaled > TI_2917HH_H_SP THEN
    TI_2917HH_H := TRUE;
ELSIF TI_2917HH_Scaled <= (TI_2917HH_H_SP - TI_2917HH_Deadband) THEN
    TI_2917HH_H := FALSE;
END_IF;
IF TI_2917HH_Scaled < TI_2917HH_L_SP THEN
    TI_2917HH_L := TRUE;
ELSIF TI_2917HH_Scaled >= (TI_2917HH_L_SP + TI_2917HH_Deadband) THEN
    TI_2917HH_L := FALSE;
END_IF;
TI_2917HH_LL_Latch(S1 := TI_2917HH_Scaled < TI_2917HH_LL_SP,
                   R  := TI_2917HH_LL_Ack AND (TI_2917HH_Scaled >= (TI_2917HH_LL_SP + TI_2917HH_Deadband)));

XI_2901A_HH_Latch(S1 := XI_2901A_Scaled > XI_2901A_HH_SP,
                  R  := XI_2901A_HH_Ack AND (XI_2901A_Scaled <= (XI_2901A_HH_SP - XI_2901A_Deadband)));
IF XI_2901A_Scaled > XI_2901A_H_SP THEN
    XI_2901A_H := TRUE;
ELSIF XI_2901A_Scaled <= (XI_2901A_H_SP - XI_2901A_Deadband) THEN
    XI_2901A_H := FALSE;
END_IF;
IF XI_2901A_Scaled < XI_2901A_L_SP THEN
    XI_2901A_L := TRUE;
ELSIF XI_2901A_Scaled >= (XI_2901A_L_SP + XI_2901A_Deadband) THEN
    XI_2901A_L := FALSE;
END_IF;
XI_2901A_LL_Latch(S1 := XI_2901A_Scaled < XI_2901A_LL_SP,
                  R  := XI_2901A_LL_Ack AND (XI_2901A_Scaled >= (XI_2901A_LL_SP + XI_2901A_Deadband)));

XI_2901B_HH_Latch(S1 := XI_2901B_Scaled > XI_2901B_HH_SP,
                  R  := XI_2901B_HH_Ack AND (XI_2901B_Scaled <= (XI_2901B_HH_SP - XI_2901B_Deadband)));
IF XI_2901B_Scaled > XI_2901B_H_SP THEN
    XI_2901B_H := TRUE;
ELSIF XI_2901B_Scaled <= (XI_2901B_H_SP - XI_2901B_Deadband) THEN
    XI_2901B_H := FALSE;
END_IF;
IF XI_2901B_Scaled < XI_2901B_L_SP THEN
    XI_2901B_L := TRUE;
ELSIF XI_2901B_Scaled >= (XI_2901B_L_SP + XI_2901B_Deadband) THEN
    XI_2901B_L := FALSE;
END_IF;
XI_2901B_LL_Latch(S1 := XI_2901B_Scaled < XI_2901B_LL_SP,
                  R  := XI_2901B_LL_Ack AND (XI_2901B_Scaled >= (XI_2901B_LL_SP + XI_2901B_Deadband)));

PumpA_StartCmd := (HS_2901A OR HS_START_STOP_A_2901A) AND NOT SAFE_STATE;
PumpA_StopCmd  := SAFE_STATE OR HS_2901A2;
PumpA_LatchS   := PumpA_StartCmd AND NOT PumpA_StopCmd;
PumpA_LatchR   := PumpA_StopCmd;
IF PumpA_LatchS THEN
    PumpA_Run := TRUE;
ELSIF PumpA_LatchR THEN
    PumpA_Run := FALSE;
END_IF;

PumpB_StartCmd := (HS_2901B OR HS_START_STOP_B_2901B) AND NOT SAFE_STATE;
PumpB_StopCmd  := SAFE_STATE OR HS_2901B2;
PumpB_LatchS   := PumpB_StartCmd AND NOT PumpB_StopCmd;
PumpB_LatchR   := PumpB_StopCmd;
IF PumpB_LatchS THEN
    PumpB_Run := TRUE;
ELSIF PumpB_LatchR THEN
    PumpB_Run := FALSE;
END_IF;

XV_Enable_A := PumpA_Run AND NOT SAFE_STATE;
XV_Enable_B := PumpB_Run AND NOT SAFE_STATE;

XV_RS_001A_TOP := XV_Enable_A;
XV_RS_001A_BOT := XV_Enable_A;
XV_RS_001B_TOP := XV_Enable_B;
XV_RS_001B_BOT := XV_Enable_B;

IF NOT SAFE_STATE THEN
    MCC_2901A := PumpA_Run AND (HS_2901A1 OR HS_2901A);
    MCC_2901B := PumpB_Run AND (HS_2901B1 OR HS_2901B);

    HY_2903A_Error    := HY_2903A_SP - TT_2909_Scaled;
    HY_2903A_Integral := HY_2903A_Integral + (HY_2903A_Ki * HY_2903A_Error);
    IF HY_2903A_Integral > 100.0 THEN
        HY_2903A_Integral := 100.0;
    ELSIF HY_2903A_Integral < 0.0 THEN
        HY_2903A_Integral := 0.0;
    END_IF;
    HY_2903A_Output_Pct := (HY_2903A_Kp * HY_2903A_Error) + HY_2903A_Integral;
    IF HY_2903A_Output_Pct > 100.0 THEN
        HY_2903A_Output_Pct := 100.0;
    ELSIF HY_2903A_Output_Pct < 0.0 THEN
        HY_2903A_Output_Pct := 0.0;
    END_IF;
    HY_2903A_Out := REAL_TO_INT(6554.0 + (HY_2903A_Output_Pct / 100.0) * (32767.0 - 6554.0));

    HY_2903B_Error    := HY_2903B_SP - TT_2917_Scaled;
    HY_2903B_Integral := HY_2903B_Integral + (HY_2903B_Ki * HY_2903B_Error);
    IF HY_2903B_Integral > 100.0 THEN
        HY_2903B_Integral := 100.0;
    ELSIF HY_2903B_Integral < 0.0 THEN
        HY_2903B_Integral := 0.0;
    END_IF;
    HY_2903B_Output_Pct := (HY_2903B_Kp * HY_2903B_Error) + HY_2903B_Integral;
    IF HY_2903B_Output_Pct > 100.0 THEN
        HY_2903B_Output_Pct := 100.0;
    ELSIF HY_2903B_Output_Pct < 0.0 THEN
        HY_2903B_Output_Pct := 0.0;
    END_IF;
    HY_2903B_Out := REAL_TO_INT(6554.0 + (HY_2903B_Output_Pct / 100.0) * (32767.0 - 6554.0));

    KV_2904_Error    := KV_2904_SP - TT_2911_Scaled;
    KV_2904_Integral := KV_2904_Integral + (KV_2904_Ki * KV_2904_Error);
    IF KV_2904_Integral > 100.0 THEN
        KV_2904_Integral := 100.0;
    ELSIF KV_2904_Integral < 0.0 THEN
        KV_2904_Integral := 0.0;
    END_IF;
    KV_2904_Output_Pct := (KV_2904_Kp * KV_2904_Error) + KV_2904_Integral;
    IF KV_2904_Output_Pct > 100.0 THEN
        KV_2904_Output_Pct := 100.0;
    ELSIF KV_2904_Output_Pct < 0.0 THEN
        KV_2904_Output_Pct := 0.0;
    END_IF;
    KV_2904_Out := REAL_TO_INT(6554.0 + (KV_2904_Output_Pct / 100.0) * (32767.0 - 6554.0));
ELSE
    MCC_2901A    := FALSE;
    MCC_2901B    := FALSE;
    HY_2903A_Out := 6554;
    HY_2903B_Out := 6554;
    KV_2904_Out  := 6554;
END_IF;

System_Alarm :=
    TI_2909_HH_Latch.Q1   OR TI_2909_LL_Latch.Q1   OR TI_2909_H   OR TI_2909_L   OR
    TT_2909_HH_Latch.Q1   OR TT_2909_LL_Latch.Q1   OR TT_2909_H   OR TT_2909_L   OR
    TT_2911_HH_Latch.Q1   OR TT_2911_LL_Latch.Q1   OR TT_2911_H   OR TT_2911_L   OR
    TT_2917_HH_Latch.Q1   OR TT_2917_LL_Latch.Q1   OR TT_2917_H   OR TT_2917_L   OR
    TI_2917HH_HH_Latch.Q1 OR TI_2917HH_LL_Latch.Q1 OR TI_2917HH_H OR TI_2917HH_L OR
    XI_2901A_HH_Latch.Q1  OR XI_2901A_LL_Latch.Q1  OR XI_2901A_H  OR XI_2901A_L  OR
    XI_2901B_HH_Latch.Q1  OR XI_2901B_LL_Latch.Q1  OR XI_2901B_H  OR XI_2901B_L  OR
    LOOP_2917_TRIP OR LOOP_2901A_TRIP OR LOOP_2901B_TRIP OR SAFE_STATE;
